class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def maxPathSum(root):
    def dfs(node):
        if not node:
            return float('-inf')
        if not node.left and not node.right:
            return node.val
        left_sum = dfs(node.left)
        right_sum = dfs(node.right)
        return node.val + max(left_sum, right_sum)
    return dfs(root)
